const writtenPitch={ 'Sol':67,'Fa':65,'Mi':64,'Re':62,'Do':60,'Si':59,'La':57,'Pes Sol':55 };
function practiceMicSpec(g,i,item){
  const group=exercises[g].group, title=item[0];
  const tokens=title.match(/Pes Sol|Sol|Fa|Mi|Re|Do|Si|La/g)||[];
  const notes=tokens.map(v=>writtenPitch[v]).filter(Number.isFinite);
  if(group==='Duy ve Çal'){
    if(i===2)return {mode:'attack',count:4,help:'Motifi duyduktan sonra dört ayrı ritim sesi çıkar. Kesin ritim eşleşmesi ölçülmez.'};
    if(i===3)return {mode:'sequence',notes:[67,67,64,62,64,62,60],sec:0.42,help:'Sol Sol Mi Re | Mi Re Do motifini sırayla çal.'};
    if(i===1)return {mode:'pitch',notes:[67],sec:0.75,help:'Örnek Sol notasını dinle, ardından kendi sesini eşleştir.'};
    return {mode:'level',sec:1,help:'Farklı sesleri dinle ve duyduğunu çal. Pes/tiz farkını kulağınla seçmen gerekiyor.'};
  }
  if(group==='Dil ve Artikülasyon'){
    if(i===0)return {mode:'attack',count:4,help:'Dört ayrı ses başlangıcını dene.'};
    if(i===2)return {mode:'attack',count:8,help:'Sekiz ayrı ses başlangıcını dene.'};
    if(i===3)return {mode:'attack',count:4,help:'Dört vuruş çal; vurgu kalitesi elle dinlenmelidir.'};
    return {mode:'sequence',notes:[67,64,62],sec:0.45,help:'Üç notayı sırayla dene; bağlı/dilli olma kalitesi ölçülmez.'};
  }
  if(group==='Nefes ve Sabitlik'){
    const seconds=Number((title.match(/(\d+) saniye/)||[])[1]||3);
    return {mode:'pitch',notes:notes.slice(0,1).length?notes.slice(0,1):[67],sec:seconds,help:'Uzun sesi akorttan fazla sapmadan kesintisiz tut. Nefes tekniği ayrıca gözlemlenmelidir.'};
  }
  if(group==='Uzun Ses'){
    const seconds=Number((title.match(/(\d+) saniye/)||[])[1]||3);
    return {mode:'pitch',notes:notes.slice(0,1).length?notes.slice(0,1):[67],sec:seconds,help:'Hedef notayı kesintisiz çal; süre ve yaklaşık akort sapması ölçülsün.'};
  }
  if(notes.length>1)return {mode:'sequence',notes,sec:0.48,help:'Notaları sırayla çal. Geçiş kalitesi ve parmak tekniği öğretmenin gözetiminde değerlendirilmelidir.'};
  return {mode:'pitch',notes:notes.length?notes:[67],sec:0.8,help:'Hedef notayı çal ve akort geri bildirimini izle.'};
}

// v4: library integration. abcjs (MIT) draws real notation; Pitchy (0BSD) detects monophonic pitch.
// The other open-source projects informed learning flow, but no AGPL OpenVox code was copied.
const OPEN_SOURCE_LIBS={
  abcjs:'https://cdn.jsdelivr.net/npm/abcjs@6.7.1/dist/abcjs-basic-min.js',
  pitchy:'https://esm.sh/pitchy@4.1.0'
};
let abcPromise=null,pitchyPromise=null;
function loadAbcJs(){
 if(window.ABCJS?.renderAbc)return Promise.resolve(window.ABCJS);
 if(abcPromise)return abcPromise;
 abcPromise=new Promise((resolve,reject)=>{
  const tag=document.createElement('script');
  tag.src=OPEN_SOURCE_LIBS.abcjs;tag.async=true;tag.crossOrigin='anonymous';
  tag.onload=()=>window.ABCJS?.renderAbc?resolve(window.ABCJS):reject(new Error('abcjs yüklenemedi'));
  tag.onerror=()=>reject(new Error('Nota kütüphanesine erişilemiyor'));
  document.head.appendChild(tag);
 });
 return abcPromise;
}
function loadPitchy(){
 if(!pitchyPromise)pitchyPromise=import(OPEN_SOURCE_LIBS.pitchy).then(x=>x.PitchDetector).catch(()=>null);
 return pitchyPromise;
}
const abcTokens={55:'G,',57:'A,',59:'B,',60:'C',62:'D',64:'E',65:'F',67:'G',69:'A',71:'B',72:'c',74:'d',76:'e',77:'f'};
function scoreHtml(notes,title='Porte ile çal'){
 const clean=notes.filter(n=>abcTokens[n]);
 if(!clean.length)return '';
 const body=clean.join(',')==='67,67,64,62,64,62,60'?'G G E D | E D C2 |]':`${clean.map(n=>abcTokens[n]).join(' ')} |]`;
 const abc=`X:1\nT:${title}\nM:4/4\nL:1/4\nK:C\n${body}`;
 const idx=noteMidi.indexOf(clean[0]);
 const fallback=(idx>=0?staffSvg(idx):`<div class="offline-score">${safe(soundName(clean[0]))} · Portede gösterim yükleniyor</div>`)
  +(clean.length>1?`<p class="offline-phrase">Nota sırası: ${clean.map(soundName).join(' · ')}</p>`:'');
 return `<section class="live-score-card" aria-label="Gerçek nota gösterimi"><div class="live-score-head"><strong>🎼 ${safe(title)}</strong><span id="notationState">Nota görünümü</span></div><div class="live-score" id="liveScore" data-abc="${encodeURIComponent(abc)}">${fallback}</div><p class="live-score-note">Yazılı notalar gösterilir; Sol (G) klarnette sesler tam dörtlü aşağı duyulur. İnternet yoksa basit porte görünümü kalır.</p></section>`;
}
async function hydrateNotation(){
 const el=document.getElementById('liveScore');if(!el)return;
 const status=document.getElementById('notationState');
 try{
  const abc=await loadAbcJs();if(!el.isConnected)return;
  const code=decodeURIComponent(el.dataset.abc||'');
  abc.renderAbc(el,code,{responsive:'resize',staffwidth:340,scale:1.1,paddingtop:9,paddingbottom:5,add_classes:true});
  if(status&&status.isConnected)status.textContent='Gerçek porte ✓';
 }catch(err){
  if(status&&status.isConnected)status.textContent='Basit porte';
 }
}
function currentNoteBadge(spec){
 if(spec.mode!=='sequence'||!spec.notes?.length)return '';
 return `<div class="mic-sequence" aria-label="Öğrenilen nota sırası">${spec.notes.map((n,i)=>`<span class="mic-seq-note ${i===0?'now':''}" data-step="${i}">${safe(soundName(n))}</span>`).join('')}</div>`;
}
function updateNoteBadges(position){
 document.querySelectorAll('.mic-seq-note').forEach((chip,i)=>{
  chip.classList.toggle('done',i<position);chip.classList.toggle('now',i===position);
 });
}
function detectPitchSample(session,sampleRate){
 if(session.pitchy){
  try{const [hz,clarity]=session.pitchy.findPitch(session.buffer,sampleRate);
   if(Number.isFinite(hz)&&hz>105&&hz<1200&&clarity>=0.86)return hz;
   return null;
  }catch{session.pitchy=null;}
 }
 return detectMicPitch(session.buffer,sampleRate);
}
let sequenceAudio=null;
function playReferenceSequence(writtenNotes){
 if(!writtenNotes?.length)return;
 try{
  sequenceAudio=sequenceAudio||new (window.AudioContext||window.webkitAudioContext)();
  if(sequenceAudio.state==='suspended')sequenceAudio.resume();
  const base=sequenceAudio.currentTime+0.08;
  writtenNotes.forEach((m,i)=>{
   const t=base+i*0.64,osc=sequenceAudio.createOscillator(),volume=sequenceAudio.createGain();
   osc.type='sine';osc.frequency.value=micPitchHz(concertMidi(m));
   volume.gain.setValueAtTime(.0001,t);volume.gain.exponentialRampToValueAtTime(.11,t+.035);
   volume.gain.setValueAtTime(.11,t+.45);volume.gain.exponentialRampToValueAtTime(.0001,t+.56);
   osc.connect(volume);volume.connect(sequenceAudio.destination);osc.start(t);osc.stop(t+.58);
  });
 }catch(e){const info=document.getElementById('micFeedback');if(info)info.textContent='Örnek ses bu tarayıcıda çalınamadı.';}
}

function stopMicrophone(){
  micGeneration++;
  const old=micController;micController=null;
  if(!old)return;
  if(old.frame)cancelAnimationFrame(old.frame);
  if(old.stream)old.stream.getTracks().forEach(t=>t.stop());
  if(old.context)old.context.close().catch(()=>{});
}
function micWidget(spec){
  const notes=spec.notes||[];
  const cue=notes.length?`<div class="mic-target">Yazılı: <strong>${notes.map(soundName).join(' · ')}</strong><span>Duyulması beklenen: ${notes.map(n=>soundName(concertMidi(n))).join(' · ')}</span></div>`:'';
  const need=spec.mode==='attack'?`${spec.count} ses başlangıcı`:spec.mode==='sequence'?`${notes.length} nota`:spec.mode==='pitch'?`${spec.sec||1} sn doğru nota`:`${spec.sec||2} sn kesintisiz ses`;
  return `<section class="mic-lab" id="micLab" aria-label="Mikrofonlu uygulama">
      <div class="mic-lab-head"><span class="mic-orb">🎙</span><div><strong>Mikrofonlu uygulama</strong><small>Gerçek sesini dinleyerek çalış</small></div><span class="mic-lab-status" id="micState">Kapalı</span></div>
      <p class="mic-instruction">${safe(spec.help||'Klarnetinle bir ses çal.')}</p>
      ${cue}${currentNoteBadge(spec)}<div class="mic-controls"><button class="mic-toggle" id="micToggle" type="button">🎙 Mikrofonu Aç</button>${notes.length?('<button class="mic-ref" id="micReference" type="button">♫ '+(notes.length>1?'Motifi dinle':'Referans sesi')+'</button>'):''}</div>
      <div class="mic-meter" aria-label="Canlı mikrofon ses seviyesi"><div id="micFill"></div></div>
      <div class="mic-telemetry"><div><small>ALGILANAN SES</small><strong id="micHeard">—</strong></div><div><small>AKORT / SÜRE</small><strong id="micDetail">—</strong></div></div>
      <p class="mic-feedback" id="micFeedback" role="status" aria-live="polite">Mikrofonu açınca canlı ses analizi başlar.</p><div class="mic-progressline"><span>Hedef: ${safe(need)}</span><span id="micProgress">Hazır</span></div>
      <p class="mic-engine" id="micEngine">Analiz: Ses algılama hazırlanıyor · Pitchy destekli</p><p class="mic-privacy">🔒 Kayıt yapılmaz, ses sunucuya gönderilmez. Mikrofon yalnız sen açınca çalışır. Çalgının türünü ayırt etmez.</p>
    </section>`;
}
function bindMicWidget(spec){
  const toggle=document.getElementById('micToggle');
  if(!toggle)return;
  toggle.onclick=()=>{if(micController||toggle.dataset.pending==='yes')stopMicrophoneAndReset();else startMicrophone(spec);};
  const ref=document.getElementById('micReference');
  if(ref)ref.onclick=()=>{
    const notes=spec.notes||[];
    if(!notes.length)return;
    const p=document.getElementById('micFeedback');
    if(micController){if(p)p.textContent='Örnek sesin mikrofona karışmaması için önce mikrofonu kapat.';return;}
    playReferenceSequence(spec.mode==='sequence'?notes:[notes[0]]);
    if(p)p.textContent=spec.mode==='sequence'?'Sentetik motif çalındı. Mikrofonu açıp sırayla tekrar et.':'Sentetik referans çalındı. Mikrofonu açıp klarnetinle eşleştir.';
  };
}
function stopMicrophoneAndReset(){
  stopMicrophone();
  const btn=document.getElementById('micToggle');if(btn){btn.dataset.pending='';btn.textContent='🎙 Mikrofonu Aç';}
  const state=document.getElementById('micState');if(state){state.textContent='Kapalı';state.className='mic-lab-status';}
  const p=document.getElementById('micFeedback');if(p)p.textContent='Mikrofon kapatıldı. Ses işlenmiyor.';
  const fill=document.getElementById('micFill');if(fill)fill.style.width='0%';
  const done=document.getElementById('donePractice');if(done)done.disabled=true;
}
// YIN difference-based monophonic pitch estimate, evaluated on 11 kHz downsampled waveform.
// Relative pitch only; without a real clarinet recording we cannot validate real-world accuracy.
function detectMicPitch(wave,sampleRate){
  const stride=Math.max(1,Math.round(sampleRate/11025)),n=2048;
  const x=new Float32Array(n),start=wave.length-stride*n;
  if(start<0)return null;
  for(let i=0;i<n;i++)x[i]=wave[start+i*stride];
  const hzSample=sampleRate/stride;
  const min=Math.max(2,Math.floor(hzSample/950)),max=Math.min(170,Math.floor(hzSample/115));
  const d=new Float32Array(max+2);
  for(let tau=1;tau<=max;tau++){
    let sum=0;for(let i=0;i<n-max;i++){const z=x[i]-x[i+tau];sum+=z*z;}
    d[tau]=sum;
  }
  let running=0,best=0,bestScore=1;
  for(let tau=1;tau<=max;tau++){
    running+=d[tau];const score=d[tau]*(tau/(running||1));
    if(tau>=min&&score<bestScore){bestScore=score;best=tau;}
    if(tau>=min&&score<0.15){
      if(tau<max&&d[tau+1]<d[tau])continue;
      best=tau;bestScore=score;break;
    }
  }
  if(!best||bestScore>.23)return null;
  // Fine adjustment near the minimum in the raw difference curve.
  const y1=d[Math.max(1,best-1)],y2=d[best],y3=d[Math.min(max,best+1)];
  const denominator=2*(y1-2*y2+y3);
  const offset=Math.abs(denominator)>1e-9?(y1-y3)/denominator:0;
  const refined=best+Math.max(-0.5,Math.min(0.5,offset));
  const freq=hzSample/refined;
  return freq>110&&freq<1000?freq:null;
}
async function startMicrophone(spec){
  stopMicrophone();
  const ticket=micGeneration;
  const btn=document.getElementById('micToggle');if(!btn)return;
  btn.dataset.pending='yes';btn.textContent='Mikrofon izni isteniyor…';
  const state=document.getElementById('micState');if(state)state.textContent='İzin bekleniyor';
  let stream=null,context=null;
  try{
    if(!window.isSecureContext||!navigator.mediaDevices?.getUserMedia)throw new Error('Bu özellik HTTPS veya localhost üzerinde desteklenen bir tarayıcı ister.');
    stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false},video:false});
    if(ticket!==micGeneration||!document.getElementById('micToggle')){stream.getTracks().forEach(t=>t.stop());return;}
    const AC=window.AudioContext||window.webkitAudioContext;
    if(!AC)throw new Error('Tarayıcın canlı ses analizini desteklemiyor.');
    context=new AC();await context.resume();
    if(ticket!==micGeneration||!document.getElementById('micToggle')){stream.getTracks().forEach(t=>t.stop());context.close();return;}
    const source=context.createMediaStreamSource(stream),analyser=context.createAnalyser();
    analyser.fftSize=8192;analyser.smoothingTimeConstant=0;
    source.connect(analyser); // Intentionally not connected to speakers: prevents feedback.
    const session={stream,context,analyser,frame:0,buffer:new Float32Array(8192),pitchy:null,last:performance.now(),lastRun:0,held:0,progress:0,passed:false,quiet:true,attacks:0,lastAttack:0};
    micController=session;btn.dataset.pending='';btn.textContent='■ Mikrofonu Kapat';
    const engine=document.getElementById('micEngine');if(engine)engine.textContent='Analiz: Yerleşik YIN · Pitchy yükleniyor…';
    loadPitchy().then(Ctor=>{
     if(micController!==session)return;
     if(Ctor){session.pitchy=Ctor.forFloat32Array(session.buffer.length);if(engine)engine.textContent='Analiz: Pitchy · gerçek zamanlı nota takibi';}
     else if(engine)engine.textContent='Analiz: Yerleşik YIN (çevrimdışı yedek)';
    });
    if(state){state.className='mic-lab-status live';state.textContent='Canlı';}
    const feedback=document.getElementById('micFeedback');if(feedback)feedback.textContent='Klarnetini çal. Sessiz ortamda ve hoparlörden uzakta ölçüm daha iyi olur.';
    const needMs=(spec.sec||1)*1000;
    const notes=spec.notes||[];
    function frame(time){
      if(micController!==session)return;
      session.frame=requestAnimationFrame(frame);
      if(time-session.lastRun<90)return;
      const dt=Math.min(250,time-session.last),elapsed=time-session.last;
      session.last=time;session.lastRun=time;
      analyser.getFloatTimeDomainData(session.buffer);
      let sum=0;for(let i=0;i<session.buffer.length;i+=4)sum+=session.buffer[i]*session.buffer[i];
      const rms=Math.sqrt(sum/(session.buffer.length/4));
      const active=rms>0.014;
      const fill=document.getElementById('micFill');if(fill)fill.style.width=Math.min(100,Math.max(0,(rms-.006)*600))+'%';
      const heard=document.getElementById('micHeard'),detail=document.getElementById('micDetail'),msg=document.getElementById('micFeedback'),prog=document.getElementById('micProgress');
      if(!heard||!detail||!msg||!prog){stopMicrophone();return;}
      let pitch=null,midi=null,cents=0;
      if(active){pitch=detectPitchSample(session,context.sampleRate);if(pitch){midi=Math.round(69+12*Math.log2(pitch/440));cents=Math.round(1200*Math.log2(pitch/micPitchHz(midi)));}}
      heard.textContent=active?(pitch?`${soundName(midi)} · ${Math.round(pitch)} Hz`:'Ses algılandı'):'Sessizlik';
      const target=(spec.mode==='sequence'?notes[Math.min(session.progress,notes.length-1)]:notes[0]);
      const targetSound=target===undefined?null:concertMidi(target);
      const off=targetSound===null||!pitch?null:Math.round(1200*Math.log2(pitch/micPitchHz(targetSound)));
      if(spec.mode==='pitch'||spec.mode==='sequence'){
        const ok=active&&off!==null&&Math.abs(off)<=65;
        if(session.waitForRelease){if(!active){session.waitForRelease=false;session.held=0;}else session.held=0;}else session.held=ok?session.held+dt:0;
        detail.textContent=off===null?'Nota bekleniyor':`${off>=0?'+':''}${off} cent`;
        if(!session.passed){
          if(!active)msg.textContent=`${soundName(targetSound)} konser sesini çal.`;
          else if(!pitch)msg.textContent='Ses var ama nota belirgin değil. Daha uzun ve temiz üflemeyi dene.';
          else if(ok)msg.textContent='✓ Doğru nota duyuluyor, sesi sabit tut.';
          else msg.textContent=`Hedef ${soundName(targetSound)}. Duyulan ${soundName(midi)}. ${off>0?'Biraz daha pes':'Biraz daha tiz'} sesi dene.`;
        }
        if(ok&&!session.waitForRelease&&session.held>=needMs){
          session.held=0;session.progress++;updateNoteBadges(session.progress);
          if(spec.mode==='sequence'&&session.progress<notes.length&&notes[session.progress]===notes[session.progress-1])session.waitForRelease=true;
          if(session.progress>=notes.length){session.passed=true;}
          else msg.textContent=session.waitForRelease?`✓ ${session.progress}. nota tamam. Tekrar çalmak için kısa bir ara ver.`:`✓ ${session.progress}. nota algılandı. Sıradaki: ${soundName(concertMidi(notes[session.progress]))}.`;
        }
        prog.textContent=spec.mode==='sequence'?`${Math.min(session.progress,notes.length)}/${notes.length} nota`:`${session.passed?100:Math.min(100,Math.round(session.held/needMs*100))}%`;
      }else if(spec.mode==='attack'){
        if(!active)session.quiet=true;
        if(active&&session.quiet&&time-session.lastAttack>170){session.attacks++;session.quiet=false;session.lastAttack=time;}
        detail.textContent=`${session.attacks} / ${spec.count} atak`;
        if(!session.passed)msg.textContent=active?'Ses başlangıçları dinleniyor. Her notadan önce kısa bir ayrım bırak.':'Kısa ve ayrı sesler üret.';
        session.passed=session.attacks>=spec.count;
        prog.textContent=`${Math.min(session.attacks,spec.count)}/${spec.count} atak`;
      }else{
        session.held=active?session.held+dt:0;
        detail.textContent=active?`${(session.held/1000).toFixed(1)} sn`:'0.0 sn';
        if(!session.passed)msg.textContent=active?'Ses seviyesi algılanıyor. Kesintisiz ve rahat üflemeyi sürdür.':'Klarnetinden ses bekleniyor.';
        prog.textContent=`${Math.min(100,Math.round(session.held/needMs*100))}%`;
        if(session.held>=needMs)session.passed=true;
      }
      if(session.passed){
        if(state){state.className='mic-lab-status passed';state.textContent='Ölçüldü ✓';}
        msg.textContent=spec.mode==='attack'?'✓ İstenen sayıda ses başlangıcı algılandı. Bu ritim veya artikülasyon kalite puanı değildir.':spec.mode==='level'?'✓ Kesintisiz ses süresi ölçüldü. Nefes tekniğinin doğruluğu hakkında kesin karar verilemez.':'✓ Hedef nota/sıra mikrofonla algılandı. Ölçüm ortam ve akort ayarına göre değişebilir.';
        const done=document.getElementById('donePractice');if(done){done.disabled=false;done.textContent='✓ Ölçülen çalışmayı tamamla';}
      }
    }
    session.frame=requestAnimationFrame(frame);
  }catch(e){
    if(stream)stream.getTracks().forEach(t=>t.stop());
    if(context)context.close().catch(()=>{});
    if(ticket!==micGeneration)return;
    btn.dataset.pending='';btn.textContent='🎙 Mikrofonu Tekrar Dene';
    if(state){state.className='mic-lab-status';state.textContent='Açılamadı';}
    const fb=document.getElementById('micFeedback');
    if(fb)fb.textContent=e.name==='NotAllowedError'?'Mikrofon izni verilmedi. Tarayıcı adres çubuğundan izin verip tekrar dene.':e.name==='NotFoundError'?'Mikrofon bulunamadı. Bağlı bir mikrofon kontrol et.':e.name==='NotReadableError'?'Mikrofon başka bir uygulamada kullanılıyor olabilir.':(e.message||'Mikrofon açılamadı.');
  }
}

