function showLesson(id){stopMicrophone();page='dersler';const l=lessons[id-1];let answer=-1;main.innerHTML=`<button class="back" id="back">‹ Derslere dön</button><div class="eyebrow">${safe(moduleInfo.find(m=>m.id===l.m).name)} · ${id}. ders</div><h1 class="bighead">${safe(l.t)}</h1><div class="lessonhero"><div class="tag">HEDEF · ${safe(l.time)}</div><p>${safe(l.goal)}</p></div>${l.id===2?anatomySvg():(l.m==='nota'||l.t.includes('transpo')?scoreHtml([64,65,67,69],'Mi–Fa–Sol–La örneği'):'')}${l.steps.map((s,i)=>`<article class="step"><h3>${i+1}. ${safe(s[0])}</h3><p>${safe(s[1])}</p></article>`).join('')}<div class="activity"><div class="eyebrow">Öğrendiklerini uygula</div><h3>Küçük görev</h3><p>${safe(l.task)}</p><button class="secondary" id="goexercise">Alıştırmalara bak ↗</button></div>${micLessons[id]?micWidget(micLessons[id]):''}<section class="step"><div class="eyebrow">Kontrol sorusu</div><h3 style="margin-top:12px">${safe(l.quiz.q)}</h3>${l.quiz.a.map((opt,i)=>`<button class="quizbutton" data-answer="${i}">${safe(opt)}</button>`).join('')}<div class="feedback" id="feedback" aria-live="polite"></div></section><button class="primary" id="complete">${completed.has(id)?'✓ Ders tamamlandı · Sonraki derse geç':'Dersi tamamladım'}</button><p class="mini">Dersler için tamamlamayı sen onaylarsın. Sesli derslerde mikrofonlu ölçüm desteklenir; enstrüman tekniği otomatik puanlanmaz.</p>`;hydrateNotation();document.getElementById('back').onclick=()=>{page='dersler';home()};document.getElementById('goexercise').onclick=()=>setNav('alistirmalar');if(micLessons[id])bindMicWidget(micLessons[id]);main.querySelectorAll('[data-answer]').forEach(btn=>btn.onclick=()=>{if(answer!==-1)return;answer=Number(btn.dataset.answer);main.querySelectorAll('[data-answer]').forEach(b=>{b.disabled=true;b.classList.toggle('right',Number(b.dataset.answer)===l.quiz.c);b.classList.toggle('wrong',Number(b.dataset.answer)===answer&&answer!==l.quiz.c)});document.getElementById('feedback').textContent=(answer===l.quiz.c?'✓ Doğru! ':'Tekrar denemeden önce notu hatırla. ')+l.quiz.why;});document.getElementById('complete').onclick=()=>{completed.add(id);try{localStorage.setItem('klar-lesson-v2',JSON.stringify([...completed]))}catch{};if(id<lessons.length)showLesson(id+1);else{openModule=l.m;home()};window.scrollTo({top:0,behavior:'instant'})};window.scrollTo({top:0,behavior:'instant'});}
function practices(){stopMicrophone();main.innerHTML=`<div class="eyebrow">Pratik alanı</div><h1 class="bighead">Alıştırmalar</h1><p class="mini">Uzun ses, nota tekrarları ve geçişler burada. Bunlar ders değil; öğrendiklerini pekiştiren çalışmalar.</p>${exercises.map(g=>`<div class="sectionbar"><h2>${safe(g.group)}</h2><span class="pill">${g.items.length} çalışma</span></div>${g.items.map((e,i)=>`<section class="exercise"><div class="row"><h3>${safe(e[0])}</h3><span class="smallchip">Alıştırma</span></div><p>${safe(e[1])}</p><button class="secondary" data-practice="${exercises.indexOf(g)}:${i}">Çalışmayı aç ›</button></section>`).join('')}`).join('')}`;main.querySelectorAll('[data-practice]').forEach(b=>b.onclick=()=>{const [g,i]=b.dataset.practice.split(':').map(Number);showPractice(g,i)});}
function showPractice(g,i){stopMicrophone();
 const x=exercises[g].items[i];const id=`${g}-${i}`;const spec=practiceMicSpec(g,i,x);
 main.innerHTML=`<button class="back" id="backPractice">‹ Alıştırmalara dön</button><div class="eyebrow">${safe(exercises[g].group)} · Alıştırma</div><h1 class="bighead">${safe(x[0])}</h1>
 <div class="lessonhero"><div class="tag">KLARNETLE UYGULA</div><p>${safe(x[1])}</p></div>
 <section class="step"><h3>Nasıl çalışacağım?</h3><p>Önce klarnetini hazırla. Mikrofonu aç ve örneği çal. Canlı ses seviyeni, algılanabilirse notanı ve yaklaşık akort farkını gör. Her gün kısa tekrarlar yap.</p></section>
 ${spec.notes?.length?scoreHtml(spec.notes,spec.mode==='sequence'?'Notaları sırayla çal':'Hedef nota'):''}${micWidget(spec)}<button class="secondary" id="donePractice" disabled>✓ Ölçüm sonrası tamamla</button><p class="microphone-note">Ses kontrolü başarılı olunca alıştırma tamamlanabilir. Gerekirse uzmanla veya öğretmenle ses kaliteni kontrol et.</p><div class="feedback" id="practiceFeedback" aria-live="polite"></div>`;
 document.getElementById('backPractice').onclick=()=>setNav('alistirmalar');
 bindMicWidget(spec);hydrateNotation();
 document.getElementById('donePractice').onclick=()=>{
  if(!micController?.passed){document.getElementById('practiceFeedback').textContent='Önce mikrofonla ses ölçümünü tamamla.';return;}
  let done=[];try{done=JSON.parse(localStorage.getItem('klar-practice-v2')||'[]')}catch{};
  if(!done.includes(id))done.push(id);
  try{localStorage.setItem('klar-practice-v2',JSON.stringify(done))}catch{}
  document.getElementById('practiceFeedback').textContent='✓ Ses ölçümüne göre tamamlandı olarak kaydedildi.';
  document.getElementById('donePractice').disabled=true;
 };
}
function staffSvg(idx){const y=[146,135,125,115,105,95,85,75,65][idx];return `<div class="staff"><svg viewBox="0 0 340 175" role="img" aria-label="Sol anahtarlı beş çizgili porte ve ${safe(noteNames[idx])} notası"><g stroke="#494350" stroke-width="2">${[65,85,105,125,145].map(y=>`<path d="M20 ${y}H320"/>`).join('')}</g><text x="22" y="141" font-size="91" fill="#514753" font-family="Georgia">𝄞</text><ellipse cx="207" cy="${y}" rx="13" ry="9" transform="rotate(-20 207 ${y})" fill="#3e304f"/><path d="M219 ${y}v-52" stroke="#3e304f" stroke-width="3"/><text x="258" y="${y+4}" fill="#3e304f" font-family="Georgia" font-size="17">${safe(noteNames[idx])}</text></svg></div>`;}
let audio=null;function playTone(midi){try{audio=audio||new (window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();let o=audio.createOscillator(),g=audio.createGain(),now=audio.currentTime;o.type='sine';o.frequency.value=440*Math.pow(2,(midi-69)/12);g.gain.setValueAtTime(.0001,now);g.gain.exponentialRampToValueAtTime(.13,now+.03);g.gain.exponentialRampToValueAtTime(.0001,now+.8);o.connect(g);g.connect(audio.destination);o.start(now);o.stop(now+.82);}catch{document.getElementById('soundInfo').textContent='Bu tarayıcıda ses çalınamıyor.'}}
function notesPage(){stopMicrophone();const i=selected;main.innerHTML=`<div class="eyebrow">Gerçek nota öğretimi</div><h1 class="bighead">Porte üzerinde öğren</h1><p class="mini">Notaya dokun, yerini gör ve referans sesini dinle. Aşağıdaki ses sentetiktir, gerçek klarnet kaydı değildir.</p>${scoreHtml([noteMidi[i]],'Bugünün notası')}<div class="notes">${noteNames.map((n,j)=>`<button class="notechip ${i===j?'sel':''}" data-note="${j}">${n}</button>`).join('')}</div><div class="example"><strong>Yazılı nota:</strong> ${noteNames[i]} · <strong>Sol klarnette duyulan:</strong> ${['Si','Do','Re','Mi','Fa♯','Sol','La','Si','Do'][i]} (konser sesine dönüşüm, tam dörtlü aşağı) </div><div class="row" style="display:flex;gap:9px"><button class="secondary" id="written" style="flex:1">♫ Yazılı sesi dinle</button><button class="secondary" id="concert" style="flex:1">◎ Duyulan sesi dinle</button></div><p class="mini" id="soundInfo" aria-live="polite">Sentetik referans tonu; parmak şeması değil.</p>${micWidget({mode:'pitch',notes:[noteMidi[i]],sec:1,help:`Yazılı ${noteNames[i]} notasını klarnetinle çal. Duyulan ses, Sol klarnete göre otomatik karşılaştırılır.`})}<div class="infobox">Önemli: Bu ekran porte okuma ve yazılı/duyulan nota farkını öğretir. Albert sistemi parmak haritası model doğrulaması olmadan otomatik uydurulmamalıdır.</div><section class="step"><h3>🎵 Duyduğunu klarnetle çal</h3><p>4/4 · Sol Sol Mi Re | Mi Re Do — |</p><p>Önce motifi dinle. Sonra mikrofona çal; her nota doğru algılandığında sıradaki işaretlenecek.</p><button class="secondary" id="melodyExercise">Motifi çalış ›</button></section>`;main.querySelectorAll('[data-note]').forEach(x=>x.onclick=()=>{selected=Number(x.dataset.note);notesPage()});hydrateNotation();document.getElementById('written').onclick=()=>playTone(noteMidi[i]);document.getElementById('concert').onclick=()=>playTone(noteMidi[i]-5);bindMicWidget({mode:'pitch',notes:[noteMidi[i]],sec:1,help:`Yazılı ${noteNames[i]} notasını klarnetinle çal. Duyulan ses, Sol klarnete göre otomatik karşılaştırılır.`});document.getElementById('melodyExercise').onclick=()=>showPractice(5,3);}
function progress(){stopMicrophone();let pct=Math.round(completed.size/lessons.length*100);main.innerHTML=`<div class="eyebrow">İlerlemen</div><h1 class="bighead">Öğrenme yolculuğun</h1><div class="lessonhero"><div class="tag">DERS İLERLEMESİ</div><h1 style="font-size:32px;margin:9px 0">%${pct}</h1><div class="progress"><i style="width:${pct}%"></i></div><p>${completed.size} / ${lessons.length} konulu ders tamamlandı.</p></div>${moduleInfo.map(m=>{const ls=lessons.filter(l=>l.m===m.id),n=ls.filter(l=>completed.has(l.id)).length;return `<section class="exercise"><div class="row"><h3>${safe(m.name)}</h3><span class="smallchip">${n}/${ls.length}</span></div><div class="progress"><i style="width:${Math.round(n/ls.length*100)}%"></i></div></section>`}).join('')}<p class="mini">İlerleme yalnızca bu tarayıcıda tutulur. Açık kaynak: abcjs (MIT), Pitchy (0BSD); Sight-Reading Trainer ve Doinu (MIT) eğitim akışına ilham verdi. Ses algılama temel bir yardımcıdır; nefes, ağız tekniği ve müzikalite uzman değerlendirmesi gerektirir.</p>`;}
nav.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>setNav(b.dataset.page)));render();

/* Progressive visual enhancements: keep original course, microphone and navigation behavior. */
(()=>{
 'use strict';
 const main=document.getElementById('main');
 const SMALL_ART=`<svg viewBox="0 0 190 285" aria-hidden="true"><defs><linearGradient id="v5body" x1="0" y1="0" x2="1" y2="0"><stop stop-color="#070e18"/><stop offset=".4" stop-color="#30373c"/><stop offset="1" stop-color="#080d14"/></linearGradient><linearGradient id="v5metal" x1="0" x2="1" y2="1"><stop stop-color="#f5deac"/><stop offset=".5" stop-color="#8d8f9e"/><stop offset="1" stop-color="#f1d29a"/></linearGradient></defs><g transform="translate(13 0) rotate(19 85 130)"><path d="M82 8L95 8L99 25L79 25Z" fill="#cfaa79"/><rect x="76" y="24" width="27" height="30" rx="7" fill="url(#v5body)" stroke="#c8b285" stroke-width="2"/><rect x="73" y="52" width="33" height="19" rx="5" fill="url(#v5metal)"/><rect x="77" y="67" width="25" height="165" rx="9" fill="url(#v5body)" stroke="#b1a391" stroke-width="2"/><path d="M77 227H103L126 269Q89 282 52 269Z" fill="url(#v5body)" stroke="#dbc18e" stroke-width="2"/><path d="M64 270Q90 280 114 270" stroke="#bd9f77" stroke-width="3" fill="none"/><g fill="none" stroke="url(#v5metal)" stroke-width="3"><path d="M77 84H103M77 112H103M77 142H103M77 173H103M77 206H103"/><path d="M75 112L64 120L64 149L76 155M101 140L116 149L116 191L102 204"/></g><g fill="#cfba9a" stroke="#d7d1be" stroke-width="1"><circle class="ring" cx="89" cy="86" r="9"/><circle class="ring" cx="89" cy="115" r="9"/><circle class="ring" cx="89" cy="146" r="9"/><circle class="ring" cx="89" cy="176" r="9"/><circle class="ring" cx="89" cy="210" r="9"/><circle cx="62" cy="137" r="7"/><circle cx="115" cy="166" r="7"/></g></g><g><path class="v5-sound" d="M9 86Q-1 110 9 133"/><path class="v5-sound" d="M19 75Q5 109 20 144"/><path class="v5-sound" d="M166 55Q183 81 166 108"/></g></svg>`;
 const BARS=Array.from({length:19},(_,i)=>`<i style="--n:${i}"></i>`).join('');
 const QUICK=`<div class="v5-section-title v5-reveal"><h2>Bugün Ne Çalışalım?</h2><small>Dinle · öğren · çal</small></div><div class="v5-quick-grid v5-reveal">
   <button type="button" class="v5-quick lesson" data-v5-action="lesson"><span class="v5-qicon">𝄞</span><span class="v5-kicker">EĞİTİM</span><strong>Dersler</strong><small>29 konulu müzik akademisi</small></button>
   <button type="button" class="v5-quick breath" data-v5-action="breath"><span class="v5-qicon">◉</span><span class="v5-decoration">${BARS.slice(0,0)||Array.from({length:8},(_,i)=>`<i style="--n:${i}"></i>`).join('')}</span><span class="v5-kicker">NEFES</span><strong>Uzun Ses</strong><small>Mikrofonlu ton egzersizi</small></button>
   <button type="button" class="v5-quick ear" data-v5-action="ear"><span class="v5-qicon">♫</span><span class="v5-decoration">${Array.from({length:8},(_,i)=>`<i style="--n:${i}"></i>`).join('')}</span><span class="v5-kicker">KULAK</span><strong>Duy ve Çal</strong><small>Motifi dinle, sonra çal</small></button>
   <button type="button" class="v5-quick tune" data-v5-action="tune"><span class="v5-qicon">◎</span><span class="v5-decoration">${Array.from({length:8},(_,i)=>`<i style="--n:${i}"></i>`).join('')}</span><span class="v5-kicker">CANLI ANALİZ</span><strong>Akort</strong><small>Çaldığın notayı ölç</small></button>
  </div>`;
 function enhance(){
   const hero=main.querySelector('.hero');
   if(hero&&!hero.dataset.v5&&!hero.classList.contains('v6-hero')){hero.dataset.v5='yes';hero.insertAdjacentHTML('beforeend',`<div class="v5-art">${SMALL_ART}<span class="v5-float n2" style="right:9px;top:40px">♪</span><span class="v5-float n3" style="right:110px;top:185px">♫</span></div>`);const stats=main.querySelector('.stats');if(stats)stats.insertAdjacentHTML('afterend',QUICK);}
   if(!hero&&main.querySelector('#liveScore')&&!main.querySelector('.v5-note-strip')&&main.querySelector('.bighead')?.textContent.includes('Porte üzerinde öğren')){
    const h=main.querySelector('.bighead');h.insertAdjacentHTML('afterend',`<div class="v5-note-strip v5-reveal"><span class="v5-music-icon" aria-hidden="true">♫</span><div><strong>Nota canlanıyor</strong><small>Notaya dokun, sesi dinle, klarnetinle karşılık ver</small></div></div>`);
   }
   const src=main.querySelector('.source');if(src&&!main.querySelector('.v5-photo-credit'))src.insertAdjacentHTML('afterend',`<p class="v5-photo-credit">Fotoğraflar: <a target="_blank" rel="noopener noreferrer" href="https://commons.wikimedia.org/wiki/File:Instrument_-_clarinet_01.jpg">Horst J. Meuter</a> (CC BY-SA 4.0), <a target="_blank" rel="noopener noreferrer" href="https://commons.wikimedia.org/wiki/File:AllanVache.jpg">Allan Vaché</a> (CC BY-SA 3.0), <a target="_blank" rel="noopener noreferrer" href="https://commons.wikimedia.org/wiki/File:Person_holds_headphones_while_playing_acoustic_guitar_and_has_sheet_music_on_the_table_at_home.jpg">Shixart1985</a>, <a target="_blank" rel="noopener noreferrer" href="https://commons.wikimedia.org/wiki/File:Tuner_and_Metronome.jpg">Gizlog</a> (CC BY-SA 3.0). Kartlarda koyu kırpma/renk geçişi uygulanmıştır.</p>`);
   main.querySelectorAll('.mic-lab').forEach(lab=>{if(lab.dataset.v5)return;lab.dataset.v5='yes';const head=lab.querySelector('.mic-lab-head');if(head)head.insertAdjacentHTML('afterend',`<div class="v5-spectrum-wrap" aria-hidden="true"><span class="v5-spectrum-label">SES DALGASI</span><div class="v5-spectrum">${BARS}</div></div>`);});
 }
 let queued=false;const observer=new MutationObserver(()=>{if(queued)return;queued=true;queueMicrotask(()=>{queued=false;enhance()})});
 observer.observe(main,{childList:true});enhance();
 document.addEventListener('click',event=>{const btn=event.target.closest('[data-v5-action]');if(!btn)return;const a=btn.dataset.v5Action;
  if(a==='lesson'){const t=main.querySelector('[data-module="tanima"]');if(t){if(t.getAttribute('aria-expanded')!=='true')t.click();document.querySelector('.modules')?.scrollIntoView({behavior:'smooth',block:'start'});}return;}
  if(a==='breath'){window.showPractice(0,0);window.scrollTo({top:0,behavior:'instant'});return;}
  if(a==='ear'){window.showPractice(5,3);window.scrollTo({top:0,behavior:'instant'});return;}
  if(a==='tune'){window.setNav('nota');return;}
 });
 // Meter reflects real RMS analysis written by V4; never fake note detection or microphone availability.
 let tick=0;const reduced=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 setInterval(()=>{const lab=main.querySelector('.mic-lab');if(!lab)return;const state=lab.querySelector('#micState');const live=!!state?.classList.contains('live');const passed=!!state?.classList.contains('passed');lab.classList.toggle('v5-mic-active',live);lab.classList.toggle('v5-mic-passed',passed);const level=live?Math.max(0,Math.min(100,parseFloat(lab.querySelector('#micFill')?.style.width)||0)):0;tick+=.42;
  for(const [i,bar] of [...lab.querySelectorAll('.v5-spectrum i')].entries()){
   const height=live&&!reduced?Math.max(5,Math.min(35,6+level*.22*(.36+.64*Math.abs(Math.sin(tick+i*.59)))+Math.abs(Math.sin(tick*.76+i*.34))*3)):5+(i%5)*1.3;
   bar.style.height=height.toFixed(1)+'px';
  }
 },130);
})();

